package net.civeira.phylax.features.access.trustedclient.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class LogoUriVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property logo uri of trusted client ")
  void test_logo_uri_v_o_builder() {
    Assertions.assertFalse(LogoUriVO.nullValue().getLogoUri().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(LogoUriVO.tryFrom(null).getLogoUri().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", LogoUriVO.from("one").getLogoUri().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> LogoUriVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", LogoUriVO.from("one").toString());
  }
}
